import { MeshBasicNodeMaterial, Group, Mesh, PlaneGeometry, Color, DoubleSide, FrontSide } from 'three/webgpu';
import { uniform, float, mix, smoothstep, vec3, uv as uvNode } from 'three/tsl';
import { gsap } from 'gsap';

const COLORS = {
  ink: '#16161d',
  paper: '#e8ecf2',
  accent: '#ff2a38',
  surface: '#0b0b10',
};

export default function createNode(config, ctx) {
  const scenePos = config.scenePosition ?? { position: [2.5, 1.6, 0], rotation: [0, 0, 0], scale: [1, 1, 1] };
  const colors = config.intent?.visualSpec?.colors ?? COLORS;

  const group = new Group();
  group.position.set(...(scenePos.position ?? [2.5, 1.6, 0]));
  group.rotation.set(...(scenePos.rotation ?? [0, 0, 0]));
  group.scale.set(...(scenePos.scale ?? [1, 1, 1]));

  const timelines = [];
  const disposables = [];

  // Card dimensions (aspect ~ 512:320)
  const cardW = 2.4;
  const cardH = 1.5;
  const stripH = 0.32;

  // ---- Image plane ----
  const imageGeo = new PlaneGeometry(cardW, cardH - stripH);
  disposables.push(imageGeo);

  const imageMat = new MeshBasicNodeMaterial({ side: FrontSide, toneMapped: true });
  // subtle dark vignette via TSL to keep it on-stage
  const v = uvNode();
  const vig = smoothstep(float(0.0), float(0.55), v.x.mul(float(-1.0)).add(float(1.0)).add(vig2(v)).abs());
  imageMat.colorNode = null; // texture sets base
  disposables.push(imageMat);

  const imagePlane = new Mesh(imageGeo, imageMat);
  imagePlane.position.y = stripH / 2;
  group.add(imagePlane);

  // ---- Caption strip (surface color) ----
  const stripGeo = new PlaneGeometry(cardW, stripH);
  disposables.push(stripGeo);
  const stripMat = new MeshBasicNodeMaterial({
    color: new Color(colors.surface ?? COLORS.surface),
    side: FrontSide,
    toneMapped: true,
  });
  disposables.push(stripMat);
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.y = -(cardH - stripH) / 2 - stripH / 2 + stripH / 2 * 0 + (-(cardH/2 - stripH/2));
  // place strip at bottom: image occupies upper (cardH-stripH)/2, strip occupies bottom stripH/2
  strip.position.y = -(cardH - stripH) / 2;
  group.add(strip);

  // ---- Accent edge (thin line at top of strip, the "signal" highlight) ----
  const edgeGeo = new PlaneGeometry(cardW, 0.02);
  disposables.push(edgeGeo);
  const edgeMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent ?? COLORS.accent),
    side: FrontSide,
    toneMapped: false,
    transparent: true,
    opacity: 0.0,
  });
  disposables.push(edgeMat);
  const edgeLine = new Mesh(edgeGeo, edgeMat);
  edgeLine.position.y = -(cardH - stripH) / 2 + stripH / 2 - 0.01;
  group.add(edgeLine);

  // ---- Card frame (thin ink border to read on dark stage) ----
  const frameGeo = new PlaneGeometry(cardW + 0.04, cardH + 0.04);
  disposables.push(frameGeo);
  const frameMat = new MeshBasicNodeMaterial({
    color: new Color(colors.ink ?? COLORS.ink),
    side: FrontSide,
    toneMapped: true,
  });
  disposables.push(frameMat);
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.z = -0.01;
  group.add(frame);

  // ---- Contact shadow under card ----
  const shadowGeo = new PlaneGeometry(cardW * 1.2, 0.6);
  disposables.push(shadowGeo);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color(0x000000),
    transparent: true,
    opacity: 0.45,
    toneMapped: true,
    side: FrontSide,
  });
  disposables.push(shadowMat);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.y = -(cardH / 2) - 0.18;
  shadow.position.z = -0.02;
  group.add(shadow);

  // transfer emissive-ish highlight factor (frame opacity uniform) — keep simple for basic material

  // ---- Load image texture ----
  const url = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (url) {
    ctx.textureLoader.loadTexture(url).then((tex) => {
      tex.colorSpace = ctx.THREE.SRGBColorSpace !== undefined ? ctx.THREE.SRGBColorSpace : (tex.colorSpace = 'srgb');
      imageMat.map = tex;
      imageMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- Interactions ----
  const restY = 0;
  const hoverTL = gsap.timeline({ paused: true });
  hoverTL.to(group.position, { y: restY + 0.15, duration: 0.7, ease: 'power3.out' }, 0)
         .to(edgeMat, { opacity: 1.0, duration: 0.4, ease: 'power2.out' }, 0);
  timelines.push(hoverTL);

  const handlers = {
    onPointerEnter: () => { hoverTL.play(); },
    onPointerLeave: () => { hoverTL.reverse(); },
    onPointerDown: () => { gsap.to(group.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' }); },
    onPointerUp: () => { gsap.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power4.out' }); },
    onClick: () => { ctx.emit('hub-journal.select', { card: config.id ?? 'journal-thumbnail' }); },
    onFocus: () => { gsap.to(edgeMat, { opacity: 1.0, duration: 0.3, ease: 'power2.out' }); },
    onBlur: () => { if (!group.userData._hover) gsap.to(edgeMat, { opacity: 0.0, duration: 0.4, ease: 'power2.out' }); },
  };
  group.userData.handlers = handlers;
  group.userData._hover = false;

  // entrance animation
  const intro = gsap.timeline();
  intro.from(group.position, { y: restY + 0.4, duration: 0.7, ease: 'power3.out' })
       .from(group.scale, { x: 0.9, y: 0.9, z: 0.9, duration: 0.9, ease: 'power4.out' }, 0)
       .from(imageMat, { opacity: 0, duration: 0.5, ease: 'power2.out' }, 0);
  imageMat.transparent = true;
  timelines.push(intro);

  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    disposables.forEach((d) => { try { d.dispose(); } catch (e) {} });
  };

  return group;
}

// helper: 2D vignette factor reused in node graph — inlined simple radial
function vig2(uv) {
  const d = uv.sub(vec3(0.5, 0.5, 0.0)).length();
  return smoothstep(float(0.25), float(0.7), d);
}
